sign_label <- function(x) {
  if (x > 0) {
    return("positive")
  }
  "not positive"
}
sign_label(5)
sign_label(-2)

grouped_mean <- function(df, group_var, mean_var) {
  df |>
    group_by({{ group_var }}) |>
    summarize(mean = mean(mean_var, na.rm = TRUE))
}
grouped_mean(flights, origin, arr_delay)

